CREATE TABLE app_private.us_analysis_locks(filing_id uuid PRIMARY KEY REFERENCES public.us_filings(id),lease uuid NOT NULL,expires_at timestamptz NOT NULL);
REVOKE ALL ON app_private.us_analysis_locks FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.sb_us_claim_analysis(fid uuid,lease uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE acquired uuid;BEGIN IF EXISTS(SELECT 1 FROM public.us_analyses WHERE filing_id=fid) THEN RETURN false;END IF;INSERT INTO app_private.us_analysis_locks VALUES(fid,lease,now()+interval '5 minutes') ON CONFLICT(filing_id) DO UPDATE SET lease=EXCLUDED.lease,expires_at=EXCLUDED.expires_at WHERE us_analysis_locks.expires_at<now() RETURNING filing_id INTO acquired;RETURN acquired IS NOT NULL;END $$;
CREATE FUNCTION public.sb_us_release_analysis(fid uuid,lease uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ DELETE FROM app_private.us_analysis_locks WHERE filing_id=fid AND us_analysis_locks.lease=sb_us_release_analysis.lease $$;
REVOKE ALL ON FUNCTION public.sb_us_claim_analysis(uuid,uuid),public.sb_us_release_analysis(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sb_us_claim_analysis(uuid,uuid),public.sb_us_release_analysis(uuid,uuid) TO service_role;
CREATE FUNCTION public.sb_us_review(fid uuid,decision text,reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE r jsonb;u text:=(SELECT auth.uid())::text;BEGIN IF NOT app_private.sb_is_admin() THEN RAISE EXCEPTION 'admin_required' USING ERRCODE='PT403';END IF;PERFORM public.sb_rate_limit();IF decision NOT IN ('approved','rejected') OR length(trim(coalesce(reason,''))) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'review_reason_required' USING ERRCODE='PT422';END IF;UPDATE public.us_analyses SET status=decision WHERE filing_id=fid AND result->>'validation'='quote_substring_and_numeric_check' RETURNING jsonb_build_object('filing_id',filing_id,'status',status) INTO r;IF r IS NULL THEN RAISE EXCEPTION 'validated_analysis_not_found' USING ERRCODE='PT404';END IF;INSERT INTO public.audit_logs(id,actor_id,action,target_id,details,created_at) VALUES(gen_random_uuid()::text,u,'us_analysis_review',fid::text,jsonb_build_object('status',decision,'reason',reason)::json,now());RETURN r;END $$;
REVOKE ALL ON FUNCTION public.sb_us_review(uuid,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.sb_us_review(uuid,text,text) TO authenticated;
COMMENT ON TABLE public.us_filings IS 'Recent US SEC filing metadata. A filing row is not an approved financial analysis.';
COMMENT ON TABLE public.us_analyses IS 'Bounded excerpt analysis; requires human semantic review before being visible to ordinary users.';
NOTIFY pgrst,'reload schema';
